    pub const FRAME_STRIDE: u32 = 0x49; // halfwords from one track (voice) to the next
    pub const SLOT_BASE: u32 = 0x19; // slot of knob 0
    pub const KNOBS: u32 = 0x8; // knobs per machine
    pub const HANG_KNOB0_FRAME_OFF: u32 = 0x0;
